import {ROLES,EVENTS,MEMBERS,PHASES,createSession,record,elapsed,startPause,finish,visibleEvents,releaseEvent,addProposal,endorse,adopt,advisor,exportSummary} from './model.js';

const KEY='water-diplomacy-lab-v1';
const $=s=>document.querySelector(s);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;
try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored?.version===1&&Array.isArray(stored.sessions)&&stored.sessions.length&&stored.sessions.every(s=>s.id&&s.name&&Array.isArray(s.released)&&Array.isArray(s.proposals)&&Array.isArray(s.history)&&s.drafts&&s.chats))data=stored;}catch{}
data??={version:1,sessions:[createSession()],current:null,role:'facilitator'};
if(!ROLES[data.role])data.role='facilitator';
if(!data.sessions.some(s=>s.id===data.current))data.current=data.sessions[0].id;
let page=['overview','brief','events','advisor','agreement','review'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
let toastTimer;
const current=()=>data.sessions.find(s=>s.id===data.current);
const activeRole=()=>ROLES[data.role];
const isFacilitator=()=>data.role==='facilitator';
function notify(text,error=false){const t=$('#toast');t.textContent=text;t.className='toast'+(error?' error-toast':'');t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{notify('Browser storage is unavailable or full. Export your workshop summary before leaving.',true);return false;}}
function formatTime(ms){const seconds=Math.floor(ms/1000);return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
const when=value=>new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
const roleName=r=>ROLES[r]?.name??r;
const btn=(label,action,extra='',primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(label,cls='')=>`<span class="tag ${cls}">${escape(label)}</span>`;
function header(kicker,title,description,actions=''){return `<div class="page-header"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="actions no-margin">${actions}</div>`:''}</div>`;}
const empty=(title,text,action='')=>`<div class="empty"><h3>${title}</h3><p>${text}</p>${action?`<div class="actions">${action}</div>`:''}</div>`;
function navigate(next){page=next;location.hash=next;render();$('#main').focus({preventScroll:true});}
const map=()=>`<svg class="basin" viewBox="0 0 400 190" role="img" aria-label="Schematic: Estara upstream, Koral Dam in Ardania on the Nera tributary, Beloria downstream, Cordinia to the west and Demeria toward the sea. Not a geographical map."><path d="M240 8C220 28 242 49 217 70S244 107 218 130S245 163 211 185" fill="none" stroke="#9ccbc1" stroke-width="10" stroke-linecap="round"/><path d="M79 63C111 57 139 83 158 92S195 104 226 112" fill="none" stroke="#9ccbc1" stroke-width="6" stroke-linecap="round"/><g fill="#71877e" font-size="11" font-family="Arial"><text x="261" y="27">ESTARA</text><text x="84" y="39">ARDANIA</text><text x="254" y="119">BELORIA</text><text x="257" y="174">DEMERIA</text><text x="16" y="151">CORDINIA</text><text x="136" y="73" font-size="9" fill="#6f9891">Nera tributary</text></g><circle cx="127" cy="77" r="8" fill="#e0a66a" stroke="#fff" stroke-width="3"/><text x="79" y="108" font-size="10" fill="#956032" font-family="Arial">Koral Dam</text><circle cx="225" cy="111" r="5" fill="#11686b" stroke="#fff" stroke-width="2"/><path d="M184 184h80" stroke="#d8e7e1" stroke-width="2" stroke-dasharray="3 3"/><text x="168" y="186" font-size="8" fill="#8c9e98">SEA</text></svg>`;
function overview(s){
 const f=isFacilitator(),events=visibleEvents(s,data.role),agreed=s.proposals.filter(p=>p.status==='agreed');
 const action=s.status==='ended'?btn('View session review →','go','data-page="review"',true):f?btn(s.status==='running'?'Pause exercise':'Start / resume exercise','toggle','',true):btn('Read my role →','go','data-page="brief"',true);
 return header('THE SAHARI BASIN WORKSHOP',f?'A space to practise cooperation.':activeRole().mission,f?'Guide a fictional negotiation, introduce a crisis and help the group reflect on its decisions.':`You represent ${activeRole().name}. Understand your mandate, respond to changing information and negotiate with the other delegations.`,f?btn('+ New workshop','new'):'')+`<div class="grid"><div class="stack"><section class="hero"><div class="eyebrow">SCENARIO 01 / SHARED WATER, SHARED RESPONSIBILITY</div><h2>One river.<br>Different interests.<br>A decision to make.</h2><p>Five fictional countries share the Sahari Basin. The failure of the Koral Dam will test how they cooperate under uncertainty.</p><div class="actions">${action}${btn(f?'Manage crisis events':'Open crisis inbox','go','data-page="events"','')}</div><div class="hero-foot"><span>4 SBCC member countries</span><span>1 cooperation partner</span><span>Up to 5 measures</span></div></section><div class="stats"><div class="stat"><strong>${events.length}</strong><span>Updates available</span></div><div class="stat"><strong>${s.proposals.length}</strong><span>Proposals submitted</span></div><div class="stat"><strong>${agreed.length}<span> / 5</span></strong><span>Measures agreed</span></div></div><section class="panel"><div class="panel-heading"><h2>${f?'Your next step':'Your workspace'}</h2>${badge(f?'Facilitator':'Participant')}</div><p class="small-text muted">${f?(s.status==='ready'?'Start the exercise, then review and release the Koral Dam event. Switch to Beloria to see what a participant receives.':s.status==='ended'?'Use the session record to discuss what changed, whose voice was heard and what could be improved.':'Choose the next event deliberately. Allow time for negotiation and pause when the group needs to reflect.'):'Read your role brief, ask the guided advisor for preparation, then submit a proposal. Switch roles in this demo to explore different interests.'}</p><div class="flow"><b>Read roles</b><span>→</span><b>Negotiate</b><span>→</span><b>Respond to a crisis</b><span>→</span><b>Agree & reflect</b></div></section></div><aside class="stack"><section class="panel"><div class="panel-heading"><h2>The shared basin</h2>${badge('Fictional')}</div>${map()}<p class="map-caption">Schematic relationships · Not a hydrological model</p><div class="map-meta"><span>Nera → Sahari River</span><span>Dam host → Downstream risk</span></div></section><section class="panel"><div class="panel-heading"><h2>At the table</h2><span class="label">EXPLORE THE ROLES</span></div><div class="role-chips">${Object.entries(ROLES).filter(([id])=>id!=='facilitator').map(([id,r])=>`<button type="button" class="role-chip" data-action="role" data-role="${id}"><span class="avatar">${r.short}</span>${r.name}</button>`).join('')}</div><p class="small-text muted" style="margin-top:16px">Real workshops use people in each role. Here, you can switch perspectives to try the workflow.</p></section>${events.length?`<section class="panel"><div class="panel-heading"><h2>Latest update</h2>${badge('Released')}</div><h3>${escape(events.at(-1).title)}</h3><p class="small-text muted" style="margin-top:9px">${escape(events.at(-1).summary)}</p><div class="actions">${btn('Read update →','go','data-page="events"')}</div></section>`:''}</aside></div>`;
}
function brief(){const r=activeRole();if(isFacilitator())return header('ROLE DESIGN','Different roles. Different perspectives.','Select a country below to read its objectives and try the participant workspace.')+`<div class="stack">${Object.entries(ROLES).filter(([id])=>id!=='facilitator').map(([id,r])=>`<section class="panel"><div class="event-top"><div class="person"><span class="avatar">${r.short}</span><div><strong>${r.name}</strong><span class="tiny">${r.position}</span></div></div>${btn('Explore role →','role',`data-role="${id}"`)}</div><p class="small-text muted" style="margin-top:15px">${r.mission}</p></section>`).join('')}</div>`;
 return header('YOUR ROLE / '+r.name.toUpperCase(),r.mission,r.position)+`<div class="grid"><div class="stack"><section class="panel"><div class="panel-heading"><h2>Your priorities</h2>${badge('Country mandate')}</div><ol class="number-list">${r.interests.map(x=>`<li>${escape(x)}</li>`).join('')}</ol></section><section class="panel"><div class="panel-heading"><h2>What you could offer</h2></div><ol class="number-list">${r.offers.map(x=>`<li>${escape(x)}</li>`).join('')}</ol><div class="actions">${btn('Prepare with advisor →','go','data-page="advisor"',true)}${btn('Draft a proposal','compose')}</div></section></div><aside class="stack"><section class="panel"><div class="panel-heading"><h2>A private constraint</h2>${badge('Role-specific','private')}</div><p class="lead">${escape(r.constraint)}</p><p class="tiny muted" style="margin-top:18px">In this browser demo you can switch to any role. Real confidentiality requires server-side accounts and permissions.</p></section><section class="panel"><h3>The task</h3><p class="small-text muted" style="margin-top:12px">Negotiate up to five feasible emergency measures. Specify who acts, when they act and how the group will communicate. A useful partial agreement is a valid outcome.</p></section></aside></div>`;
}
function eventCard(e,released){return `<article class="event-row"><div class="event-top"><div><div class="eyebrow" style="margin-bottom:5px">${escape(e.category)} ${released?' / '+formatTime(e.workshopMs):''}</div><h3>${escape(e.title)}</h3></div>${badge(e.audience==='all'?'All roles':roleName(e.audience)+' only',e.audience!=='all'?'private':'')}</div><p>${escape(e.summary)}</p>${released?`<div class="event-body"><p>${escape(e.detail)}</p><div class="prompt">${escape(e.prompt)}</div></div>`:`<div class="actions">${btn('Review & release →','preview-event',`data-id="${e.id}"`,true)}</div>`}</article>`;}
function events(s){const f=isFacilitator(),items=visibleEvents(s,data.role);return header(f?'FACILITATOR / CRISIS CONTROL':'YOUR CRISIS INBOX',f?'Introduce change with purpose.':'What your delegation knows.',f?'Review an event and its audience before releasing it. Follow-up events unlock after the dam failure.':'Updates appear here when released to your role. Your advisor uses the same accessible updates.',f&&s.status!=='ended'?btn(s.status==='running'?'Pause exercise':'Start / resume','toggle'):'')+`<div class="grid"><section class="panel"><div class="panel-heading"><h2>${f?'Event queue':'Released updates'}</h2>${badge(f?'Human-controlled':items.length+' updates')}</div>${f?EVENTS.filter(e=>!s.released.some(r=>r.id===e.id)).map(e=>eventCard(e,false)).join('')||empty('All events released','Let the group finish negotiating, then move into debrief.'):items.length?[...items].reverse().map(e=>eventCard(e,true)).join(''):empty('Your inbox is ready','No crisis has been released to this role yet. The facilitator chooses when to introduce new information.')}</section><aside class="stack"><section class="panel"><h3>${f?'Release history':'Working with uncertainty'}</h3>${f?`<div style="margin-top:18px">${items.length?[...items].reverse().map(e=>`<div class="event-row"><h3>${escape(e.title)}</h3><p>${when(e.at)} · ${e.audience==='all'?'All roles':roleName(e.audience)}</p></div>`).join(''):empty('Nothing released yet','Start the exercise and release the first event.')}</div>`:`<p class="small-text muted" style="margin-top:12px">Separate confirmed information, allegations and estimates. Ask what is missing before changing your position.</p><div class="actions">${btn('Ask the advisor →','go','data-page="advisor"')}</div>`}</section>${f?`<section class="panel"><h3>Freeze the process</h3><p class="small-text muted" style="margin-top:12px">Pause for a short reflection: whose information is missing, and who has authority to act?</p><div class="actions">${btn(s.status==='running'?'Pause for reflection':'Resume exercise','toggle',s.status==='ended'?'disabled':'')}</div></section>`:''}</aside></div>`;}
function advisorPage(s){if(isFacilitator())return header('GUIDED ADVISOR','Try the participant perspective.','This example advisor helps country delegates prepare for negotiation.')+`<section class="panel">${empty('Choose a delegation','Switch to a country role to try its guided advisor.',btn('Try Beloria →','role','data-role="beloria"',true))}</section>`;
 const chats=s.chats[data.role]??[];
 return header('PREPARE / '+activeRole().name.toUpperCase(),'Think through your next move.','A guided, rule-based example that uses your role and released events. It does not call an AI service.')+`<div class="grid"><section class="panel"><div class="panel-heading"><h2>Your advisor conversation</h2>${badge('Guided example')}</div>${chats.length?chats.map(c=>`<article class="chat-message"><p class="question">${escape(c.question)}</p><div class="answer">${escape(c.answer)}</div><div class="sources">Uses: ${c.sources.map(escape).join(' · ')}</div></article>`).join(''):empty('Start with a question','Explore your priorities, possible offers or the effect of the latest crisis update.')}<form class="chat-form" id="advisor-form"><label class="label" for="advisor-question">YOUR QUESTION</label><textarea id="advisor-question" name="question" maxlength="1000" required placeholder="What could my delegation offer?" aria-label="Your question"></textarea><div class="actions no-margin"><button type="submit" class="btn primary">Get guided advice →</button><span class="save-status">Saved for this role</span></div></form></section><aside class="stack"><section class="panel"><h3>Try a question</h3><div class="suggestions">${['What should I ask first?','What can I offer?','What changed after the latest event?','Help me draft a proposal.'].map(q=>`<button type="button" class="suggestion" data-action="ask" data-question="${escape(q)}">${q}</button>`).join('')}</div></section><section class="panel"><h3>You make the decisions</h3><p class="small-text muted" style="margin-top:12px">Use suggestions as preparation. Negotiate with the other people in the workshop and choose what your delegation is willing to support.</p><div class="actions">${btn('Draft a proposal →','compose')}</div></section></aside></div>`;
}
function proposalCard(p,s){const supported=p.supporters.includes(data.role),complete=MEMBERS.every(r=>p.supporters.includes(r));return `<article class="panel proposal"><div class="event-top"><div><h3>${escape(p.title)}</h3><div class="meta">Proposed by ${roleName(p.author)} · ${when(p.at)}</div></div>${badge(p.status==='agreed'?'Agreed measure':'Open proposal',p.status==='agreed'?'agreed':'')}</div><p class="lead">${escape(p.text)}</p><div class="terms"><div><span class="label">RESPONSIBLE</span>${escape(p.owner)}</div><div><span class="label">WHEN</span>${escape(p.timing)}</div></div><div class="supporters">${MEMBERS.map(r=>`<span class="support-chip ${p.supporters.includes(r)?'yes':''}">${p.supporters.includes(r)?'✓ ':''}${roleName(r)}</span>`).join('')}${p.supporters.includes('estara')?'<span class="support-chip yes">✓ Estara (partner)</span>':''}</div>${p.status==='proposed'&&s.status!=='ended'?`<div class="actions">${isFacilitator()?btn(complete?'Record as agreed':'Awaiting member support','adopt',`data-id="${p.id}" ${complete?'':'disabled'}`,true):btn(supported?'Withdraw support':'Support this measure','support',`data-id="${p.id}"`,!supported)}<span class="tiny muted">${p.supporters.filter(r=>MEMBERS.includes(r)).length} / 4 SBCC members support</span></div>`:''}</article>`;}
function agreement(s){const agreed=s.proposals.filter(p=>p.status==='agreed');return header('THE NEGOTIATION OUTPUT','Build a workable agreement.','Submit concrete measures. Each member country records its support; the facilitator records agreed measures.',!isFacilitator()&&s.status!=='ended'?btn('+ Propose a measure','compose','',true):btn('Export summary ↓','export'))+`<div class="grid"><div><div class="panel-heading"><h2>Agreed measures</h2>${badge(agreed.length+' / 5','agreed')}</div>${agreed.length?agreed.map(p=>proposalCard(p,s)).join(''):`<section class="panel">${empty('The agreement starts here','A measure becomes agreed when all four SBCC members support it and the facilitator records it.')}</section>`}<div class="panel-heading" style="margin-top:29px"><h2>Open proposals</h2>${badge(s.proposals.length-agreed.length+' proposals')}</div>${s.proposals.some(p=>p.status==='proposed')?s.proposals.filter(p=>p.status==='proposed').map(p=>proposalCard(p,s)).join(''):`<section class="panel">${empty('No open proposals','Choose a country role and propose an emergency measure.')}</section>`}</div><aside class="stack"><section class="panel"><h3>Make every measure usable</h3><ol class="number-list" style="margin-top:18px"><li>Describe the specific action.</li><li>Name the responsible party.</li><li>Set a time or notification trigger.</li><li>Record support and remaining concerns.</li></ol></section><section class="panel"><h3>Try the full workflow</h3><p class="small-text muted" style="margin-top:12px">Submit as Beloria, then switch to Ardania, Cordinia and Demeria to record support. Switch to Facilitator to adopt the measure.</p><div class="prompt">The final mandate allows up to five measures. Prioritize what the parties can implement.</div></section></aside></div>`;}
function review(s){const history=s.history.filter(x=>x.type!=='event'||isFacilitator()||!s.released.some(e=>e.audience!=='all'&&e.audience!==data.role&&x.text.startsWith(e.title)));return header('REFLECT / LEARN / IMPROVE','The discussion is part of the outcome.','Review the workshop record, reflect on decisions and keep a useful summary.',btn('Export summary ↓','export')+(isFacilitator()&&s.status!=='ended'?btn('End exercise','finish','',true):''))+`<div class="grid"><div class="stack"><div class="stats"><div class="stat"><strong>${s.released.filter(e=>e.audience==='all').length}</strong><span>Public crisis updates</span></div><div class="stat"><strong>${s.proposals.length}</strong><span>Proposals explored</span></div><div class="stat"><strong>${s.proposals.filter(p=>p.status==='agreed').length}</strong><span>Measures agreed</span></div></div><section class="panel"><div class="panel-heading"><h2>Workshop timeline</h2>${badge(s.status==='ended'?'Completed':'In progress')}</div><ol class="timeline">${[...history].reverse().map(x=>`<li><time>${when(x.at)}</time><p>${escape(x.text)}</p></li>`).join('')}</ol></section></div><aside class="stack"><section class="panel"><h3>Questions for the group</h3><ul class="review-questions"><li>What did you know when you made each decision?</li><li>How did you communicate uncertainty?</li><li>Whose perspective was missing?</li><li>Which interests made compromise possible?</li><li>Could the agreed measures be implemented?</li></ul></section><section class="panel"><h3>Shared debrief notes</h3><form id="notes-form" class="form-grid" style="margin-top:15px"><div class="field"><label for="notes">Observations and follow-up</label><textarea id="notes" name="notes" maxlength="12000" ${isFacilitator()?'':'readonly'} placeholder="Facilitator observations, lessons and improvements…">${escape(s.notes)}</textarea></div>${isFacilitator()?'<button type="submit" class="btn">Save debrief notes</button>':'<p class="tiny muted">The facilitator records shared notes.</p>'}</form></section></aside></div>`;}
const pages={overview,brief,events,advisor:advisorPage,agreement,review};
const navigation=[['overview','Overview','◫'],['brief','Role briefs','▤'],['events','Crisis inbox','◷'],['advisor','Guided advisor','✧'],['agreement','Agreement','▣'],['review','Session review','↗']];
function render(){const s=current();$('#session-select').innerHTML=data.sessions.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${escape(x.name)}</option>`).join('');$('#role-select').innerHTML=Object.entries(ROLES).map(([id,r])=>`<option value="${id}" ${id===data.role?'selected':''}>${r.name}${id==='facilitator'?'':' · Delegate'}</option>`).join('');$('#navigation').innerHTML=navigation.map(([id,label,icon])=>`<button type="button" class="nav-link ${id===page?'active':''}" data-action="go" data-page="${id}" ${id===page?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}${id==='events'&&visibleEvents(s,data.role).length?`<span class="count">${visibleEvents(s,data.role).length}</span>`:''}</button>`).join('');$('#page-label').textContent=navigation.find(x=>x[0]===page)?.[1]??'Overview';$('#session-strip').innerHTML=`<div class="strip-left"><strong>${escape(s.name)}</strong><span class="phase-pill">${PHASES[s.phase]}</span></div><div><span class="clock" id="clock">${formatTime(elapsed(s))}</span><span class="status-text"><span class="live-dot" style="background:${s.status==='running'?'#46836b':'#a1aba5'}"></span> ${s.status==='ready'?'Ready to start':s.status==='ended'?'Completed':s.status==='paused'?'Paused':'Running'}</span></div>`;$('#main').innerHTML=pages[page](s);}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button type="button" class="btn" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-content">${body}</div>`;$('#modal').showModal();}
function compose(){if(isFacilitator())return notify('Choose a country role to propose a measure.',true);if(current().status==='ended')return notify('This workshop has ended. Create a new one to continue.',true);const d=current().drafts[data.role]??{};modal('Propose an emergency measure',`<form id="proposal-form" class="form-grid"><div class="field"><label for="proposal-title">Measure title</label><input id="proposal-title" name="title" required maxlength="120" value="${escape(d.title)}" placeholder="Emergency information-sharing channel"></div><div class="field"><label for="proposal-text">What will the parties do?</label><textarea id="proposal-text" name="text" required maxlength="2400" placeholder="Describe a specific, feasible action…">${escape(d.text)}</textarea></div><div class="two-fields"><div class="field"><label for="proposal-owner">Who is responsible?</label><input id="proposal-owner" name="owner" maxlength="120" value="${escape(d.owner)}" placeholder="National emergency focal points"></div><div class="field"><label for="proposal-timing">When?</label><input id="proposal-timing" name="timing" maxlength="120" value="${escape(d.timing)}" placeholder="Immediately, with hourly updates"></div></div><p class="tiny muted">Drafting as ${activeRole().name}. Your draft is saved as you type.</p><div class="actions no-margin"><button type="submit" class="btn primary">Submit proposal →</button><button type="button" class="btn" data-action="close-modal">Keep draft</button></div><p class="error" id="form-error" role="alert" hidden></p></form>`);}
function newWorkshop(){modal('Create a workshop',`<form id="new-form" class="form-grid"><div class="field"><label for="workshop-name">Workshop name</label><input id="workshop-name" name="name" required maxlength="80" value="Sahari Basin · Workshop ${String(data.sessions.length+1).padStart(2,'0')}"></div><p class="small-text muted">Starts a fresh Sahari/Koral exercise. Your existing workshops remain saved in this browser.</p><button type="submit" class="btn primary">Create workshop →</button></form>`);}
function ask(question){if(isFacilitator())throw Error('Choose a country role to try the advisor.');if(!question.trim())throw Error('Enter a question.');const s=current();s.chats[data.role]??=[];s.chats[data.role].push(advisor(s,data.role,question));save();render();$('#advisor-question')?.focus();}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const s=current();try{switch(b.dataset.action){case'go':navigate(b.dataset.page);return;case'role':data.role=b.dataset.role;save();navigate('brief');return;case'new':newWorkshop();return;case'close-modal':$('#modal').close();return;case'compose':compose();return;case'toggle':if(!isFacilitator())throw Error('Choose Facilitator to control the exercise.');startPause(s);break;case'preview-event':{if(!isFacilitator())throw Error('Choose Facilitator to manage events.');const ev=EVENTS.find(x=>x.id===b.dataset.id);modal(ev.title,`<div class="actions no-margin">${badge(ev.category)}${badge(ev.audience==='all'?'Audience: all roles':'Audience: '+roleName(ev.audience),ev.audience==='all'?'':'private')}</div><p>${escape(ev.detail)}</p><div class="prompt">${escape(ev.prompt)}</div><p class="tiny muted">${s.status==='running'?'This will be added to the intended roles’ inboxes.':'Start or resume the exercise before releasing this event.'}</p><div class="actions">${btn('Release to audience','release',`data-id="${ev.id}" ${s.status==='running'?'':'disabled'}`,true)}${btn('Keep in queue','close-modal')}</div>`);return;}case'release':releaseEvent(s,b.dataset.id,data.role);$('#modal').close();notify('Event released to its intended audience.');break;case'ask':ask(b.dataset.question);return;case'support':endorse(s,b.dataset.id,data.role);notify('Your delegation’s support was updated.');break;case'adopt':adopt(s,b.dataset.id,data.role);notify('Measure recorded as agreed.');break;case'finish':modal('End the exercise?',`<p>The timer will stop and proposals will become read-only. The timeline, notes and summary stay available for debrief.</p><div class="actions">${btn('End and begin debrief','confirm-finish','',true)}${btn('Continue negotiating','close-modal')}</div>`);return;case'confirm-finish':if(!isFacilitator())throw Error('Only the facilitator can end the exercise.');finish(s);$('#modal').close();save();navigate('review');return;case'export':{const blob=new Blob([exportSummary(s)],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='water-diplomacy-workshop-summary.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Summary exported. Individual briefs and advisor chats are excluded.');return;}}save();render();}catch(error){notify(error.message,true);}});
document.addEventListener('submit',e=>{if(!['new-form','proposal-form','advisor-form','notes-form'].includes(e.target.id))return;e.preventDefault();const fields=Object.fromEntries(new FormData(e.target));try{if(e.target.id==='new-form'){if(!fields.name.trim())throw Error('Enter a workshop name.');const s=createSession(fields.name);data.sessions.push(s);data.current=s.id;data.role='facilitator';$('#modal').close();save();navigate('overview');notify('Workshop created. Your earlier session is still saved.');}if(e.target.id==='proposal-form'){addProposal(current(),data.role,fields);$('#modal').close();save();navigate('agreement');notify('Proposal submitted. Switch member roles to record support.');}if(e.target.id==='advisor-form')ask(fields.question);if(e.target.id==='notes-form'){if(!isFacilitator())throw Error('Only the facilitator can save shared notes.');current().notes=fields.notes;save();notify('Debrief notes saved.');}}catch(error){const target=$('#form-error');if(target){target.textContent=error.message;target.hidden=false;}else notify(error.message,true);}});
document.addEventListener('input',e=>{if(e.target.closest('#proposal-form')){current().drafts[data.role]=Object.fromEntries(new FormData($('#proposal-form')));save();}});
$('#role-select').addEventListener('change',e=>{data.role=e.target.value;save();render();notify('Now viewing as '+activeRole().name+'.');});
$('#session-select').addEventListener('change',e=>{data.current=e.target.value;save();render();});
$('#new-session').addEventListener('click',newWorkshop);
$('#demo-about').addEventListener('click',()=>$('#how-it-works').click());
$('#how-it-works').addEventListener('click',()=>modal('A working workshop demonstration',`<p><strong>1.</strong> Start as Facilitator and release a crisis event.</p><p><strong>2.</strong> Switch to Beloria or another country to read its brief, explore guided advice and submit a proposal.</p><p><strong>3.</strong> Switch between member countries to support the proposal. Return to Facilitator to record it as agreed.</p><p><strong>4.</strong> End the exercise, save debrief notes and export the summary.</p><div class="divider"></div><p class="small-text muted">All information is fictional. This prototype stores data only in this browser. Different devices do not share sessions. Role switching demonstrates the workflow and is not authentication. The advisor uses prepared rules, not a live AI model. Do not enter sensitive information.</p>${btn('Start exploring','close-modal','',true)}`));
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(pages[next]&&page!==next){page=next;render();}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.version===1&&Array.isArray(next.sessions)&&next.sessions.some(s=>s.id===data.current)){data.sessions=next.sessions;render();}}catch{}}});
setInterval(()=>{const clock=$('#clock');if(clock)clock.textContent=formatTime(elapsed(current()));},1000);
save();render();
